import { NAVNO_ROOT_PATH } from '../../constants';

// Queries are executed by the Guillotine app, via an internal vhost mapping to its API endpoint
// (/api/com.enonic.app.guillotine:graphql). Requests are authenticated with the service secret
// (see idprovider.ts)
export const GUILLOTINE_API_URL =
    app.config.guillotineApiUrl || 'http://localhost:8080/_guillotine';

const escapeRegExp = (str: string) => str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// Page URLs generated by lib-portal during a Guillotine request have no site vhost to resolve
// against, so they are prefixed with the site endpoint path (/site/<project>/<branch>). The Guillotine
// app's own rich text processing avoids this with the site scope, but our macro callbacks use
// lib-portal directly. With lib-guillotine in XP7, URLs were generated relative to the public site
// vhost. Rewrite to match that format:
// /site/<project>/<branch>/www.nav.no/some/path -> /some/path
// /site/<project>/<branch>/_/media:image/...    -> /_/media:image/...
const loopbackPrefixPattern = `/site/[^/"\\\\]+/(?:draft|master)`;
const loopbackSiteUrlRegex = new RegExp(
    `${loopbackPrefixPattern}${escapeRegExp(NAVNO_ROOT_PATH)}(?:/|(?=["?#\\\\]))`,
    'g'
);
const loopbackApiUrlRegex = new RegExp(`${loopbackPrefixPattern}/_/`, 'g');

// XP8 generates media URLs with the project (and branch, for draft) in the path. The Guillotine app
// returns these without the /_ prefix. Layer projects are not publicly readable, so rewrite to the
// XP7 format, where the project and branch are resolved from the vhost serving the request. This is
// also the format the frontend expects.
// [/_]/media:image/<project>[:<branch>]/<id>:<hash>/...                -> /_/image/<id>:<hash>/...
// [/_]/media:attachment/<project>[:<branch>]/<id>:<hash>/...           -> /_/attachment/inline/<id>:<hash>/...
// [/_]/media:attachment/<project>[:<branch>]/<id>:<hash>/...?download  -> /_/attachment/download/<id>:<hash>/...
const mediaImageUrlRegex = /(?:\/_)?\/media:image\/[^/"'<>\\?#\s]+\//g;
const mediaAttachmentUrlRegex =
    /(?:\/_)?\/media:attachment\/[^/"'<>\\?#\s]+\/([^"'<>\\?#\s]*)(?:\?([^"'<>\\#\s]*))?/g;

// Query params may be separated by &amp; when the URL is in richtext HTML
const queryParamSeparatorRegex = /&amp;|&/;

const rewriteAttachmentUrl = (mediaPath: string, query?: string) => {
    const separator = query?.includes('&amp;') ? '&amp;' : '&';
    const params = query ? query.split(queryParamSeparatorRegex) : [];
    const otherParams = params.filter((param) => param !== 'download' && param !== '');

    const disposition = params.includes('download') ? 'download' : 'inline';
    const queryString = otherParams.length > 0 ? `?${otherParams.join(separator)}` : '';

    return `/_/attachment/${disposition}/${mediaPath}${queryString}`;
};

const rewriteMediaUrls = (str: string) =>
    str
        .replace(mediaImageUrlRegex, '/_/image/')
        .replace(mediaAttachmentUrlRegex, (_match, mediaPath: string, query?: string) =>
            rewriteAttachmentUrl(mediaPath, query)
        );

export const rewriteLoopbackUrls = (str: string) =>
    rewriteMediaUrls(str.replace(loopbackSiteUrlRegex, '/').replace(loopbackApiUrlRegex, '/_/'));
